overlay = r'''
pub(super) fn quick_plan(rules: &[Rule]) -> Result<Vec<serde_json::Value>> {
    Ok(plan_groups(rules)?.iter().enumerate().map(|(id, plan)| {
        let kind = match &plan.condition {
            GroupCondition::Primitive(_) => "exact_primitive",
            GroupCondition::LiteralTail(_) => "literal_tail",
            GroupCondition::Prefixes(_) => "prefix",
            GroupCondition::Literals(_) => "literal",
            GroupCondition::FirstBytes(_) => "first_bytes",
        };
        serde_json::json!({"group_id": id, "condition": kind, "rule_ids": plan.rule_ids})
    }).collect())
}

pub(super) fn quick_variant(rules: &[Rule], variant: &str) -> Result<GroupedMatcher> {
    let plans = plan_groups(rules)?;
    let bypass: Vec<_> = plans.iter().enumerate().filter_map(|(id, plan)| {
        let selected = match &plan.condition {
            GroupCondition::Prefixes(_) => variant == "no_prefix_routing" || variant == "no_literal_or_prefix_routing",
            GroupCondition::Literals(_) | GroupCondition::LiteralTail(_) => variant == "no_literal_routing" || variant == "no_literal_or_prefix_routing",
            _ => false,
        };
        selected.then_some((id, plan.guard))
    }).collect();
    let mut matcher = GroupedMatcher::new(rules, plans)?;
    if variant == "no_exact_primitives" || variant == "no_literal_tail_predicates" {
        let cache = (DFA_CACHE_BUDGET_PER_WORKER / matcher.groups.len()).min(MAX_GROUP_DFA_CACHE);
        for group in &mut matcher.groups {
            let replace = match &group.engine {
                GroupEngine::Primitive(_) => variant == "no_exact_primitives",
                GroupEngine::LiteralTail { .. } => variant == "no_literal_tail_predicates",
                _ => false,
            };
            if replace {
                let set = RegexSetBuilder::new(group.rule_ids.iter().map(|&id| &rules[id].expression))
                    .unicode(false).size_limit(SET_SIZE_LIMIT).dfa_size_limit(cache).build()?;
                group.engine = if group.rule_ids.len() == 1 { GroupEngine::Single(set) } else { GroupEngine::Regex(set) };
            }
        }
    }
    let index = Arc::get_mut(&mut matcher.index).unwrap();
    if variant == "no_prefix_routing" || variant == "no_literal_or_prefix_routing" {
        index.prefixes = PrefixIndex::default();
    }
    if variant == "no_literal_routing" || variant == "no_literal_or_prefix_routing" {
        index.literal_search = None;
    }
    for (id, guard) in bypass {
        for byte in 0..256 {
            if guard.first_bytes.contains(byte as u8) { index.fallback[byte].push(id); }
        }
        if guard.minimum_len == Some(0) { index.fallback[EMPTY_INPUT_BUCKET].push(id); }
    }
    Ok(matcher)
}
'''
