(work / 'main.rs').write_text(r'''
#![allow(dead_code, unused_imports)]
mod input;
mod matcher;
mod reporting;
use anyhow::{ensure, Result};
use std::{hint::black_box, path::Path, sync::Arc, time::Instant};
use input::{PatternDatabase, Request};
use matcher::{Matcher, RequestResult, ResultBuilder};

fn batch(matcher: &Matcher, builder: &ResultBuilder, requests: &[Request]) -> Vec<RequestResult> {
    requests.iter().map(|r| builder.build(r.id, matcher.matching_rules(&r.bytes))).collect()
}

fn main() -> Result<()> {
    let args: Vec<_> = std::env::args().collect();
    let inputs: Vec<serde_json::Value> = serde_json::from_slice(&std::fs::read(&args[1])?)?;
    let mut requests = Vec::new();
    let mut counts = std::collections::BTreeMap::<String, usize>::new();
    let mut bytes = 0usize;
    for item in &inputs {
        let label = item["label"].as_str().unwrap();
        input::read_requests(Path::new(item["path"].as_str().unwrap()), Some(item["limit"].as_u64().unwrap() as usize), |mut r| {
            if r.bytes.len() <= 64 * 1024 && bytes + r.bytes.len() <= 16 * 1024 * 1024 {
                bytes += r.bytes.len();
                r.id = requests.len() as u64;
                requests.push(r);
                *counts.entry(label.to_owned()).or_default() += 1;
            }
            Ok(())
        })?;
    }
    ensure!(!requests.is_empty(), "empty sample");
    let database = PatternDatabase::load(Path::new(input::PATTERNS_PATH))?;
    let plan = matcher::quick_plan(&database)?;
    std::fs::write(&args[2], serde_json::to_vec(&plan)?)?;
    let builder = ResultBuilder::new(Arc::new(database.rules.clone()));
    let baseline = Matcher::baseline(&database);
    let expected = batch(&baseline, &builder, &requests);
    let names = ["control", "no_prefix_routing", "no_literal_routing", "no_exact_primitives", "no_literal_tail_predicates", "no_literal_or_prefix_routing"];
    let mut matchers = Vec::new();
    for name in names {
        let matcher = matcher::quick_variant(&database, name)?;
        ensure!(batch(&matcher, &builder, &requests) == expected, "warmup result differs: {name}");
        matchers.push((name, matcher));
    }
    let mut results = Vec::new();
    for repetition in 0..3 {
        let order: Vec<_> = if repetition % 2 == 0 { (0..matchers.len()).collect() } else { (0..matchers.len()).rev().collect() };
        for index in order {
            let (name, matcher) = &matchers[index];
            let mut elapsed = 0.0;
            let mut batches = 0;
            while elapsed < 0.05 {
                let start = Instant::now();
                let result = batch(matcher, &builder, &requests);
                elapsed += start.elapsed().as_secs_f64();
                ensure!(result == expected, "timed result differs: {name}");
                black_box(result);
                batches += 1;
            }
            results.push(serde_json::json!({"variant":name,"repetition":repetition+1,"batches":batches,
                "elapsed_matching_seconds":elapsed,"seconds_per_batch":elapsed/batches as f64,
                "equals_baseline":true}));
        }
    }
    println!("{}", serde_json::json!({"status":"complete","requests":requests.len(),"normalized_bytes":bytes,
        "corpus_counts":counts,"input_files":inputs.len(),"max_request_bytes":requests.iter().map(|r|r.bytes.len()).max(),
        "runs":results,"all_outputs_equal_baseline":true}));
    Ok(())
}
''')

